def transform(grid):
    h, w = len(grid), len(grid[0])

    row_bounds = [r for r in range(h) if len(set(grid[r])) == 1]
    col_bounds = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    out_w = col_bounds[1] - col_bounds[0] + 1
    frame = grid[row_bounds[0]][0]
    out = [[frame] * out_w for _ in range(h)]

    for top, bottom in zip(row_bounds, row_bounds[1:]):
        if bottom == top + 1:
            continue

        panels = []
        for left, right in zip(col_bounds, col_bounds[1:]):
            panels.append([
                tuple(grid[r][c] for c in range(left + 1, right))
                for r in range(top + 1, bottom)
            ])

        def distance(a, b):
            return sum(x != y for ra, rb in zip(a, b) for x, y in zip(ra, rb))

        # The exceptional panel is the one least like the others.
        chosen = max(
            range(len(panels)),
            key=lambda i: sum(distance(panels[i], panels[j])
                              for j in range(len(panels)) if j != i)
        )

        left, right = col_bounds[chosen], col_bounds[chosen + 1]
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                out[r][c - left] = grid[r][c]

    return out
